/**
 * Multi-lingual Text-to-Speech API Endpoint
 * Uses Google Cloud Text-to-Speech API for high-quality voice synthesis
 * Supports Kinyarwanda, English, French, and more
 * Falls back to browser TTS if Google Cloud is not configured
 */

import express from 'express';
import dotenv from 'dotenv';

dotenv.config();

const router = express.Router();

// Try to import Google Cloud TTS, but don't fail if not available
let ttsClient: any = null;
try {
  const { google } = require('@google-cloud/text-to-speech');
  if (process.env.GOOGLE_CLOUD_PROJECT_ID) {
    ttsClient = new google.textToSpeech.TextToSpeechClient({
      keyFilename: process.env.GOOGLE_CLOUD_KEY_FILE || undefined,
      projectId: process.env.GOOGLE_CLOUD_PROJECT_ID,
    });
  }
} catch (error) {
  console.log('Google Cloud TTS not available, will use fallback');
}

// Voice mapping for supported languages
const VOICE_MAPPING: Record<string, string> = {
  'rw-RW': 'rw-RW-Standard-A', // Kinyarwanda
  'en-US': 'en-US-Standard-C', // English (US)
  'fr-FR': 'fr-FR-Standard-A', // French
  'default': 'en-US-Standard-C'
};

/**
 * POST /api/tts
 * Converts text to speech using Google Cloud TTS
 * 
 * Request body:
 * {
 *   text: string (required)
 *   language: string (optional, default: en-US)
 *   voiceGender: 'male' | 'female' | 'neutral' (optional, default: neutral)
 *   speakingRate: number (optional, default: 1.0)
 *   pitch: number (optional, default: 0.0)
 * }
 */
router.post('/tts', async (req, res) => {
  try {
    const { text, language = 'en-US', voiceGender = 'neutral', speakingRate = 1.0, pitch = 0.0 } = req.body;

    if (!text || typeof text !== 'string') {
      return res.status(400).json({ error: 'Text is required and must be a string' });
    }

    if (!ttsClient) {
      // Fallback to browser TTS if Google Cloud not configured
      return res.status(503).json({ 
        error: 'Google Cloud TTS not configured. Please use browser TTS fallback.',
        fallback: true
      });
    }

    // Get the appropriate voice for the language
    const voiceName = VOICE_MAPPING[language] || VOICE_MAPPING['default'];

    // Build the TTS request
    const request = {
      input: { text },
      voice: {
        languageCode: language.split('-')[0], // Extract language code (e.g., 'en' from 'en-US')
        name: voiceName,
        ssmlGender: voiceGender,
      },
      audioConfig: {
        audioEncoding: 'MP3' as const,
        speakingRate,
        pitch,
      },
    };

    // Perform the text-to-speech request
    const [response] = await ttsClient.synthesizeSpeech(request);

    // Convert the audio content to base64 for transmission
    const audioContent = response.audioContent as Uint8Array;
    const audioBase64 = Buffer.from(audioContent).toString('base64');

    res.json({
      audioContent: audioBase64,
      contentType: 'audio/mpeg',
      language,
      voice: voiceName,
    });

  } catch (error: any) {
    console.error('TTS error:', error);
    
    // Check if it's a Google Cloud authentication error
    if (error.code === 7 || error.message?.includes('UNAUTHENTICATED')) {
      return res.status(401).json({ 
        error: 'Google Cloud authentication failed. Check your credentials.',
        fallback: true
      });
    }
    
    // Check if it's a quota error
    if (error.code === 8 || error.message?.includes('RESOURCE_EXHAUSTED')) {
      return res.status(429).json({ 
        error: 'Google Cloud TTS quota exceeded. Please try again later.',
        fallback: true
      });
    }
    
    res.status(500).json({ 
      error: 'Failed to generate speech. Please try again.',
      fallback: true
    });
  }
});

/**
 * GET /api/tts/voices
 * Returns available voices for a given language
 */
router.get('/tts/voices', async (req, res) => {
  try {
    if (!ttsClient) {
      return res.status(503).json({ 
        error: 'Google Cloud TTS not configured',
        availableVoices: VOICE_MAPPING
      });
    }

    const [result] = await ttsClient.listVoices({});
    const voices = result.voices?.map(voice => ({
      name: voice.name,
      languageCodes: voice.languageCodes,
      gender: voice.ssmlGender,
      naturalSampleRate: voice.naturalSampleRateHertz,
    })) || [];

    res.json({ voices });

  } catch (error: any) {
    console.error('List voices error:', error);
    res.status(500).json({ 
      error: 'Failed to list voices',
      availableVoices: VOICE_MAPPING
    });
  }
});

export default router;
